-- QA COPY of infra/bigquery/294_mk_market_forecast.sql, generated by name mapping only
-- (mart.market_* -> mart_qa.mk_market_*, ref.client_markets / ref.naming_rules -> mart_qa.mk_*,
-- stg_customer_orders / stg_shoptet_orders -> mart_qa.mm1_* of migration 284). Do not edit by hand.

-- =============================================================================
-- 294_mk_market_forecast.sql
-- Markets page (v1c data, built now in QA): predicted 365-day GP per customer
-- for young cohorts, Option A maturity multiplier (owner 2026-10-15), plus the
-- one refresh entry point for all Markets objects.
-- Contract: docs/sessions/2026-10-15/markets/CONTRACT.md (mart_qa.mk_market_forecast).
-- Method: research/research-ltgp-prediction.md section 2 (repeat-only).
-- Backtest that set the parameters: docs/sessions/2026-10-15/markets/DATA-BUILD.md.
--
-- Creates
--   1. ref.client_markets.forecast_min_age_days (new column + values from the
--      backtest: the first age at which the multiplier beat the naive
--      baseline by >= 5 pp MAPE in that market)
--   2. mart.sp_refresh_market_forecast()  appends today's run to mart.market_forecast
--   3. mart.market_forecast               append-only, one run per run_date
--   4. mart.sp_refresh_markets()          calls 290 -> 291 -> 292 -> 293 -> forecast
--
-- Rule
--   forecast_gp365 = first-order GP per customer (actual, stays actual)
--                  + repeat GP per customer at age N (actual) x m(N)
--   m(N) = median of repeat_GP365 / repeat_GP_N over the last 12 mature
--          (365 d complete) non-Q4 monthly cohorts of the same market
--          (min 6), or the last 8 mature non-Q4 quarterly cohorts (min 3).
--   Grain: monthly when the market averaged >= 100 new customers / month
--          over the last 12 months, quarterly at 50 to 99, none below 50.
--   Q4 cohorts (Nov, Dec; quarterly: Oct to Dec) use the ratio of the same
--          month (quarter) one year earlier, flagged by n_reference_cohorts = 1.
--   N = the largest of 30 / 60 / 90 / 180 the whole cohort has reached.
--          No forecast before day 30, nor before the market's
--          forecast_min_age_days, nor at all where that is NULL (not
--          backtested yet, e.g. Ethia; owner 2026-10-15).
--   Band (about 80 %, calibrated on the backtest; the research draft's
--          P10..P90 curve + 1.28 SE covered ~100 % and was too wide to use):
--          low  = first + max(repeat_N - 0.84 SE, 0) x P25(m) x s
--          high = first + (repeat_N + 0.84 SE) x P75(m) x s
--          SE = stdev of per-customer repeat GP at N / sqrt(customers),
--          s = 1, or for Q4 = m_LY / median(pool) (pool spread moved to LY).
--   GP: product GP (net sales - COGS) of costed customers only (every order
--          within 365 d costed); per customer = over those customers.
--   method 'none' + reason_if_none for every young cohort that gets no
--          forecast (no COGS, volume, too young, before min age, references).
--   Never mixed into actuals or verdicts (contract).
--
-- Additive column beyond CONTRACT.md: customers (costed customers the
--   per-customer values are computed over). For method
--   'multiplier_quarterly', cohort_month is the first month of the quarter.
--
-- Depends on 290 (market_orders). Snapshot trap: run after 290 to 293 were
--   CALLed; this file CALLs only the forecast.
-- Refresh: mart.sp_refresh_markets(). Proposed schedule (owner): append
--   `CALL oneeighty-warehouse.mart.sp_refresh_markets();` as the LAST line of
--   the console scheduled query rpt_refresh_hourly (after the customer-entry
--   CALL, so a failure here cannot block the other refreshes), OR, cheaper,
--   a separate daily scheduled query at 05:30 UTC: one full refresh
--   processes ~4.7 GB (290 reads stg_shopify_orders payload_json and the
--   Shoptet raw dedup), about 110 GB/day if hourly.
-- QA copy: infra/bigquery/qa/294_mk_market_forecast_qa.sql.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Per-market forecast start age (from the backtest, DATA-BUILD.md)
-- -----------------------------------------------------------------------------
ALTER TABLE `oneeighty-warehouse.mart_qa.mk_client_markets`
  ADD COLUMN IF NOT EXISTS forecast_min_age_days INT64
  OPTIONS(description="First cohort age (30/60/90/180) at which a LTGP forecast is shown for this market. Set from the 294 backtest: the first age where the multiplier beat the naive baseline by >= 5 pp MAPE. NULL = no forecast (market not backtested yet; owner 2026-10-15: hide until tested).");

UPDATE `oneeighty-warehouse.mart_qa.mk_client_markets` t
SET forecast_min_age_days = s.min_age, updated_at = CURRENT_TIMESTAMP()
FROM UNNEST([
  STRUCT('dobias' AS client_id, 'US' AS market, 60 AS min_age),
  STRUCT('dobias', 'CA', 180),
  STRUCT('manami', 'CZ', 60),
  STRUCT('rawbark', 'CZ', 30),
  STRUCT('rawbark', 'SK', 30)
]) s
WHERE t.client_id = s.client_id AND t.market = s.market;

-- -----------------------------------------------------------------------------
-- 2. mart.sp_refresh_market_forecast
-- -----------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_forecast`()
OPTIONS (description = 'Appends the run of today to mart.market_forecast: 365-day GP per customer forecast for young cohorts per client x first-order market (repeat-only maturity multiplier, median of mature non-Q4 cohorts, Q4 same period last year, band P25..P75 + 0.84 SE), method none with a reason otherwise. Replaces an earlier run of the same day. Migration 294.')
BEGIN
  DECLARE run_d DATE DEFAULT CURRENT_DATE();
  DECLARE new_rows INT64;
  DECLARE dup_rows INT64;
  DECLARE bad_band INT64;

  SET @@query_label = 'feature:markets-refresh';

  CREATE TABLE IF NOT EXISTS `oneeighty-warehouse.mart_qa.mk_market_forecast`
  (
    client_id STRING NOT NULL,
    first_order_market STRING NOT NULL,
    cohort_month DATE NOT NULL,
    as_of_age_days INT64,
    actual_gp_per_customer NUMERIC,
    forecast_gp365_per_customer NUMERIC,
    band_low NUMERIC,
    band_high NUMERIC,
    multiplier FLOAT64,
    n_reference_cohorts INT64,
    method STRING NOT NULL,
    reason_if_none STRING,
    run_date DATE NOT NULL,
    customers INT64
  )
  PARTITION BY run_date
  CLUSTER BY client_id, first_order_market
  OPTIONS (description = 'Markets: LTGP 365 forecast per young cohort, one run per run_date (append-only: when a cohort reaches 365 d the forecast-vs-actual pair is kept). Never mixed into actuals. Built by mart.sp_refresh_market_forecast (migration 294).');

  CREATE TEMP TABLE fc AS
  WITH
  settings AS (
    SELECT client_id, market, forecast_min_age_days AS min_age
    FROM `oneeighty-warehouse.mart_qa.mk_client_markets`
  ),
  as_of AS (
    SELECT client_id, LEAST(DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY), MAX(order_date)) AS as_of_date
    FROM `oneeighty-warehouse.mart_qa.mk_market_orders`
    GROUP BY client_id
  ),
  firsts AS (
    SELECT client_id, customer_key, first_order_market AS market, first_order_date AS d
    FROM `oneeighty-warehouse.mart_qa.mk_market_orders`
    WHERE is_new_customer
  ),
  pc AS (                -- per customer: first-order GP, repeat GP at each age
    SELECT f.client_id, f.market, f.d, f.customer_key,
      LOGICAL_AND(IF(o.order_date < DATE_ADD(f.d, INTERVAL 365 DAY), o.gross_profit IS NOT NULL, TRUE)) AS costed,
      SUM(IF(o.is_new_customer, o.gross_profit, 0)) AS first_gp,
      SUM(IF(NOT o.is_new_customer AND o.order_date < DATE_ADD(f.d, INTERVAL 30 DAY),  o.gross_profit, 0)) AS r30,
      SUM(IF(NOT o.is_new_customer AND o.order_date < DATE_ADD(f.d, INTERVAL 60 DAY),  o.gross_profit, 0)) AS r60,
      SUM(IF(NOT o.is_new_customer AND o.order_date < DATE_ADD(f.d, INTERVAL 90 DAY),  o.gross_profit, 0)) AS r90,
      SUM(IF(NOT o.is_new_customer AND o.order_date < DATE_ADD(f.d, INTERVAL 180 DAY), o.gross_profit, 0)) AS r180,
      SUM(IF(NOT o.is_new_customer AND o.order_date < DATE_ADD(f.d, INTERVAL 365 DAY), o.gross_profit, 0)) AS r365
    FROM firsts f
    JOIN `oneeighty-warehouse.mart_qa.mk_market_orders` o
      ON o.client_id = f.client_id AND o.customer_key = f.customer_key
    GROUP BY f.client_id, f.market, f.d, f.customer_key
  ),
  volume AS (            -- last 12 complete months: average new customers, costed share
    SELECT p.client_id, p.market,
      COUNT(*) / 12 AS avg_new,
      SAFE_DIVIDE(COUNTIF(p.costed), COUNT(*)) AS costed_share
    FROM pc p JOIN as_of a USING (client_id)
    WHERE p.d >= DATE_SUB(DATE_TRUNC(a.as_of_date, MONTH), INTERVAL 12 MONTH)
      AND p.d <  DATE_TRUNC(a.as_of_date, MONTH)
    GROUP BY p.client_id, p.market
  ),
  plan AS (
    SELECT v.client_id, v.market, v.avg_new, v.costed_share,
      CASE
        WHEN v.costed_share < 0.9 THEN 'none'
        WHEN v.avg_new < 50 THEN 'none'
        WHEN v.avg_new < 100 THEN 'quarter'
        ELSE 'month'
      END AS grain,
      CASE
        WHEN v.costed_share < 0.9 THEN 'no COGS for this client: GP and LTGP not computable'
        WHEN v.avg_new < 50 THEN FORMAT('under 50 new customers per month (last 12 months: %.0f)', v.avg_new)
      END AS plan_reason,
      s.min_age AS min_age
    FROM volume v
    LEFT JOIN settings s ON s.client_id = v.client_id AND s.market = v.market
    WHERE v.market != 'OTHER'
  ),
  g AS (
    SELECT 'month' AS grain, DATE_TRUNC(d, MONTH) AS cohort, LAST_DAY(d, MONTH) AS cohort_end, pc.* FROM pc
    UNION ALL
    SELECT 'quarter', DATE_TRUNC(d, QUARTER), LAST_DAY(d, QUARTER), pc.* FROM pc
  ),
  coh AS (
    SELECT client_id, market, grain, cohort, cohort_end,
      COUNTIF(costed) AS customers,
      AVG(IF(costed, first_gp, NULL)) AS first_pc,
      AVG(IF(costed, r30, NULL))  AS r30,  AVG(IF(costed, r60, NULL))  AS r60,
      AVG(IF(costed, r90, NULL))  AS r90,  AVG(IF(costed, r180, NULL)) AS r180,
      AVG(IF(costed, r365, NULL)) AS r365,
      STDDEV_SAMP(IF(costed, r30, NULL))  AS sd30,  STDDEV_SAMP(IF(costed, r60, NULL))  AS sd60,
      STDDEV_SAMP(IF(costed, r90, NULL))  AS sd90,  STDDEV_SAMP(IF(costed, r180, NULL)) AS sd180
    FROM g
    GROUP BY client_id, market, grain, cohort, cohort_end
  ),
  cn AS (                -- cohort x age
    SELECT c.client_id, c.market, c.grain, c.cohort, c.cohort_end, c.customers, c.first_pc, n,
      CAST(CASE n WHEN 30 THEN c.r30 WHEN 60 THEN c.r60 WHEN 90 THEN c.r90 WHEN 180 THEN c.r180 END AS FLOAT64) AS rn_v,
      CASE n WHEN 30 THEN c.sd30 WHEN 60 THEN c.sd60 WHEN 90 THEN c.sd90 WHEN 180 THEN c.sd180 END AS sd_v,
      CAST(c.r365 AS FLOAT64) AS r365,
      (c.grain = 'month' AND EXTRACT(MONTH FROM c.cohort) IN (11, 12))
        OR (c.grain = 'quarter' AND EXTRACT(QUARTER FROM c.cohort) = 4) AS is_q4,
      DATE_ADD(c.cohort_end, INTERVAL 364 DAY) <= a.as_of_date AS mature,
      DATE_ADD(c.cohort_end, INTERVAL n - 1 DAY) <= a.as_of_date AS age_reached
    FROM coh c
    JOIN as_of a USING (client_id)
    CROSS JOIN UNNEST([30, 60, 90, 180]) AS n
  ),
  ranked AS (
    SELECT client_id, market, grain, n, cohort, SAFE_DIVIDE(r365, rn_v) AS ratio,
      ROW_NUMBER() OVER (PARTITION BY client_id, market, grain, n ORDER BY cohort DESC) AS rk
    FROM cn
    WHERE mature AND NOT is_q4 AND rn_v > 0 AND customers > 0
  ),
  pool_w AS (
    SELECT client_id, market, grain, n,
      PERCENTILE_CONT(ratio, 0.5)  OVER w AS med,
      PERCENTILE_CONT(ratio, 0.25) OVER w AS p25,
      PERCENTILE_CONT(ratio, 0.75) OVER w AS p75,
      COUNT(*) OVER w AS n_ref
    FROM ranked
    WHERE rk <= IF(grain = 'month', 12, 8)
    WINDOW w AS (PARTITION BY client_id, market, grain, n)
  ),
  pool AS (
    SELECT client_id, market, grain, n,
      ANY_VALUE(med) AS med, ANY_VALUE(p25) AS p25, ANY_VALUE(p75) AS p75, ANY_VALUE(n_ref) AS n_ref
    FROM pool_w GROUP BY client_id, market, grain, n
  ),
  ly AS (                -- same month / quarter one year earlier, mature
    SELECT client_id, market, grain, n, DATE_ADD(cohort, INTERVAL 1 YEAR) AS for_cohort,
      SAFE_DIVIDE(r365, rn_v) AS ratio_ly
    FROM cn WHERE mature AND rn_v > 0 AND customers > 0
  ),
  young AS (             -- not yet 365 d mature: the largest age reached
    SELECT client_id, market, grain, cohort, customers, first_pc,
      MAX(IF(age_reached, n, NULL)) AS n_used,
      ANY_VALUE(is_q4) AS is_q4
    FROM cn
    WHERE NOT mature AND cohort <= CURRENT_DATE()
    GROUP BY client_id, market, grain, cohort, customers, first_pc
  ),
  candidates AS (        -- young cohorts at the grain the market uses (monthly for 'none')
    SELECT y.*, p.plan_reason, p.min_age, p.grain AS plan_grain
    FROM young y
    JOIN plan p
      ON p.client_id = y.client_id AND p.market = y.market
     AND y.grain = IF(p.grain = 'none', 'month', p.grain)
  ),
  scored AS (
    SELECT c.*, cn.rn_v, cn.sd_v, pl.med, pl.p25, pl.p75, pl.n_ref, l.ratio_ly,
      CASE
        WHEN c.plan_reason IS NOT NULL THEN c.plan_reason
        WHEN c.min_age IS NULL THEN 'not backtested in this market yet: forecast hidden'
        WHEN c.n_used IS NULL THEN 'cohort younger than 30 days'
        WHEN c.n_used < c.min_age THEN FORMAT('forecast starts at day %d in this market (backtest)', c.min_age)
        WHEN c.customers = 0 THEN 'no costed customers in this cohort'
        WHEN IFNULL(pl.n_ref, 0) < IF(c.grain = 'month', 6, 3)
          THEN FORMAT('only %d mature non-Q4 reference cohorts (need %d)', IFNULL(pl.n_ref, 0), IF(c.grain = 'month', 6, 3))
        WHEN c.is_q4 AND l.ratio_ly IS NULL THEN 'Q4 cohort without a mature cohort one year earlier'
      END AS reason
    FROM candidates c
    LEFT JOIN cn
      ON cn.client_id = c.client_id AND cn.market = c.market AND cn.grain = c.grain
     AND cn.cohort = c.cohort AND cn.n = c.n_used
    LEFT JOIN pool pl
      ON pl.client_id = c.client_id AND pl.market = c.market AND pl.grain = c.grain AND pl.n = c.n_used
    LEFT JOIN ly l
      ON l.client_id = c.client_id AND l.market = c.market AND l.grain = c.grain
     AND l.n = c.n_used AND l.for_cohort = c.cohort
  ),
  final AS (
    SELECT s.*,
      IF(s.is_q4, s.ratio_ly, s.med) AS m,
      IF(s.is_q4, SAFE_DIVIDE(s.ratio_ly, s.med), 1) AS sc,
      IFNULL(s.sd_v, 0) / SQRT(GREATEST(s.customers, 1)) AS se
    FROM scored s
  )
  SELECT
    f.client_id,
    f.market AS first_order_market,
    f.cohort AS cohort_month,
    f.n_used AS as_of_age_days,
    CAST(IF(f.n_used IS NULL OR f.customers = 0, NULL, f.first_pc + f.rn_v) AS NUMERIC) AS actual_gp_per_customer,
    CAST(IF(f.reason IS NULL, f.first_pc + f.rn_v * f.m, NULL) AS NUMERIC) AS forecast_gp365_per_customer,
    CAST(IF(f.reason IS NULL, f.first_pc + GREATEST(f.rn_v - 0.84 * f.se, 0) * f.p25 * f.sc, NULL) AS NUMERIC) AS band_low,
    CAST(IF(f.reason IS NULL, f.first_pc + (f.rn_v + 0.84 * f.se) * f.p75 * f.sc, NULL) AS NUMERIC) AS band_high,
    IF(f.reason IS NULL, f.m, NULL) AS multiplier,
    IF(f.reason IS NULL, IF(f.is_q4, 1, f.n_ref), NULL) AS n_reference_cohorts,
    CASE
      WHEN f.reason IS NOT NULL THEN 'none'
      WHEN f.grain = 'quarter' THEN 'multiplier_quarterly'
      ELSE 'multiplier_monthly'
    END AS method,
    f.reason AS reason_if_none,
    CURRENT_DATE() AS run_date,
    f.customers
  FROM final f;

  SET new_rows = (SELECT COUNT(*) FROM fc);
  SET dup_rows = (SELECT COUNT(*) - COUNT(DISTINCT FORMAT('%s|%s|%t', client_id, first_order_market, cohort_month)) FROM fc);
  SET bad_band = (
    SELECT COUNTIF(method != 'none' AND NOT (band_low <= forecast_gp365_per_customer
                                            AND forecast_gp365_per_customer <= band_high))
    FROM fc);

  ASSERT new_rows > 0 AS 'market_forecast: run is empty';
  ASSERT dup_rows = 0 AS 'market_forecast: duplicate client + market + cohort in one run';
  ASSERT bad_band = 0 AS 'market_forecast: forecast outside its own band';

  DELETE FROM `oneeighty-warehouse.mart_qa.mk_market_forecast` WHERE run_date = run_d;
  INSERT INTO `oneeighty-warehouse.mart_qa.mk_market_forecast`
    (client_id, first_order_market, cohort_month, as_of_age_days, actual_gp_per_customer,
     forecast_gp365_per_customer, band_low, band_high, multiplier, n_reference_cohorts,
     method, reason_if_none, run_date, customers)
  SELECT client_id, first_order_market, cohort_month, as_of_age_days, actual_gp_per_customer,
     forecast_gp365_per_customer, band_low, band_high, multiplier, n_reference_cohorts,
     method, reason_if_none, run_date, customers
  FROM fc;
END;

-- -----------------------------------------------------------------------------
-- 3. One entry point for the scheduler
-- -----------------------------------------------------------------------------
CREATE OR REPLACE PROCEDURE `oneeighty-warehouse.mart_qa.mk_sp_refresh_markets`()
OPTIONS (description = 'Refreshes every Markets object in dependency order: market_orders (290), market_spend_daily (291), market_daily (292), market_cohorts (293), market_forecast (294). Each step builds beside the live table and swaps only after its checks pass, so a failure leaves the previous version readable. Migration 294.')
BEGIN
  CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_orders`();
  CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_spend`();
  CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_daily`();
  CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_cohorts`();
  CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_forecast`();
END;

CALL `oneeighty-warehouse.mart_qa.mk_sp_refresh_market_forecast`();

